from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Bounded lossless optimizer for separator-free serialized-prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional source dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Convert a scalar to evaluator text, mapping scalar missing values to empty text."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the exact common-prefix length using binary-search string slicing."""
        high = min(len(left), len(right))
        low = 0
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Compute ideal character-Trie reuse from sorted adjacent serialized strings."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(
            cls._lcp(ordered[i - 1], ordered[i])
            for i in range(1, len(ordered))
        )

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize every row by concatenating each row's selected source columns."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    def _global_order(self, cells, mode: int) -> List[int]:
        """Rank columns by deterministic length-weighted or repetition-weighted duplication."""
        n, m = cells.shape
        ranked = []

        for column in range(m):
            counts = {}
            total_length = 0

            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1
                total_length += len(value)

            weighted = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            repeated = sum(
                count * (count - 1)
                for count in counts.values()
            )

            if mode == 0:
                score = weighted
            else:
                score = repeated * max(
                    1, total_length // max(1, n)
                )

            ranked.append((score, column))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, column in ranked]

    def _paired_orders(self, cells, global_order: List[int]) -> List[List[int]]:
        """Create bounded disjoint cross-row prefix-matching anchors and global-ranked tails.

        Candidate partners are found through short-prefix buckets over the eight
        most repetitive columns.  Each row contributes at most eight partners
        and 32 pair proposals; proposals are then selected greedily without
        reusing rows.  An accepted row begins with its selected anchor column,
        while its remaining columns retain the global frequency order.
        """
        n, m = cells.shape
        if n <= 1 or m <= 1:
            return [list(global_order) for _ in range(n)]

        # Select anchor columns using the prescribed length-weighted repetition
        # statistic, independently of the final global candidate ordering.
        ranked = []
        for column in range(m):
            counts = {}
            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1
            score = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            ranked.append((score, column))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        anchor_columns = [
            column for _, column in ranked[:min(8, m)]
        ]

        # Keep buckets bounded.  This avoids both pathological memory use and
        # large proposal sets for common prefixes such as empty strings.
        buckets = {}
        for column in anchor_columns:
            for length in (1, 2, 4):
                for row in range(n):
                    text = cells[row, column]
                    key = (column, length, text[:length])
                    bucket = buckets.setdefault(key, [])
                    if len(bucket) < 12:
                        bucket.append(row)

        proposals = []

        for row in range(n):
            partners = set()

            for column in anchor_columns:
                text = cells[row, column]
                for length in (1, 2, 4):
                    bucket = buckets.get(
                        (column, length, text[:length]),
                        (),
                    )
                    for other in bucket:
                        if other != row:
                            partners.add(other)
                            if len(partners) >= 8:
                                break
                    if len(partners) >= 8:
                        break
                if len(partners) >= 8:
                    break

            local = []
            for other in sorted(partners):
                best_weight = 0
                best_pair = None

                for left_column in anchor_columns:
                    left_text = cells[row, left_column]
                    if not left_text:
                        continue

                    for right_column in anchor_columns:
                        if left_column == right_column:
                            continue

                        weight = self._lcp(
                            left_text,
                            cells[other, right_column],
                        )
                        if weight > best_weight:
                            best_weight = weight
                            best_pair = (left_column, right_column)

                if best_pair is not None and best_weight > 0:
                    local.append((
                        best_weight,
                        row,
                        other,
                        best_pair[0],
                        best_pair[1],
                    ))

            local.sort(
                key=lambda item: (
                    -item[0],
                    item[1],
                    item[2],
                    item[3],
                    item[4],
                )
            )
            proposals.extend(local[:32])

        proposals.sort(
            key=lambda item: (
                -item[0],
                item[1],
                item[2],
                item[3],
                item[4],
            )
        )

        used = np.zeros(n, dtype=np.bool_)
        anchors = {}

        for weight, first_row, second_row, first_col, second_col in proposals:
            if used[first_row] or used[second_row]:
                continue

            used[first_row] = True
            used[second_row] = True
            anchors[first_row] = first_col
            anchors[second_row] = second_col

        result = []
        for row in range(n):
            first = anchors.get(row)
            if first is None:
                result.append(list(global_order))
            else:
                result.append(
                    [first] + [
                        column for column in global_order
                        if column != first
                    ]
                )

        return result

    def _candidate(self, cells, orders):
        """Serialize and exactly score one candidate, returning deterministic row order."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row),
        )
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate two global layouts and one matched-pair layout losslessly."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for column in range(m):
                cells[row, column] = self._cell_text(raw[row, column])

        global_a = self._global_order(cells, 0)
        global_b = self._global_order(cells, 1)
        paired = self._paired_orders(cells, global_a)

        candidates = (
            [[global_a[:] for _ in range(n)]],
            [[global_b[:] for _ in range(n)]],
            [paired],
        )

        best = None
        for candidate_group in candidates:
            orders = candidate_group[0]
            score, strings, row_order = self._candidate(cells, orders)

            signature = tuple(orders[0]) if orders else ()
            choice = (score, tuple(-column for column in signature))

            if best is None or choice > best[0]:
                best = (choice, strings, row_order, orders)

        _, strings, row_order, orders = best

        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            source_order = orders[source]
            output[destination, :] = [
                raw[source, column] for column in source_order
            ]
            column_orders.append([
                df.columns[column] for column in source_order
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders

